red"},{"testNo":2,"passageNo":3,"surface":"notion","partOfSpeech":"noun","translationUz":"tushuncha","definitionEn":"an idea or belief about something"},{"testNo":2,"passageNo":3,"surface":"philosophy","partOfSpeech":"noun","translationUz":"falsafa","definitionEn":"the systematic study of knowledge reality and reasoning"},{"testNo":2,"passageNo":3,"surface":"extremes","partOfSpeech":"noun","translationUz":"ikki qarama-qarshi qutb","definitionEn":"opposite ends of a range of possibilities"},{"testNo":2,"passageNo":3,"surface":"purist","partOfSpeech":"adjective","translationUz":"sof qoidaga qat’iy amal qiluvchi","definitionEn":"strictly adhering to the original principles of an approach"},{"testNo":2,"passageNo":3,"surface":"outcome","partOfSpeech":"noun","translationUz":"natija","definitionEn":"the result of an action or process"},{"testNo":2,"passageNo":3,"surface":"logically","partOfSpeech":"adverb","translationUz":"mantiqan","definitionEn":"in a way consistent with valid reasoning"},{"testNo":2,"passageNo":3,"surface":"expectations","partOfSpeech":"noun","translationUz":"kutilmalar","definitionEn":"beliefs about what will happen"},{"testNo":2,"passageNo":3,"surface":"whatsoever","partOfSpeech":"adverb","translationUz":"umuman hech qanday","definitionEn":"at all in any respect"},{"testNo":2,"passageNo":3,"surface":"ideal","partOfSpeech":"adjective","translationUz":"eng maqbul","definitionEn":"representing the best possible choice"},{"testNo":2,"passageNo":3,"surface":"reside","partOfSpeech":"verb","translationUz":"yotmoq yoki joylashmoq","definitionEn":"to exist or be found in a particular place"},{"testNo":2,"passageNo":3,"surface":"ignorant","partOfSpeech":"adjective","translationUz":"bexabar","definitionEn":"not knowing something"},{"testNo":2,"passageNo":3,"surface":"entertain","partOfSpeech":"verb","translationUz":"ko‘rib chiqmoq","definitionEn":"to consider an idea or possibility"},{"testNo":2,"passageNo":3,"surface":"alternative outcomes","partOfSpeech":"noun phrase","translationUz":"muqobil natijalar","definitionEn":"other possible results of a process"},{"testNo":2,"passageNo":3,"surface":"accidental","partOfSpeech":"adjective","translationUz":"tasodifiy","definitionEn":"happening without a deliberate plan"},{"testNo":2,"passageNo":3,"surface":"aspect","partOfSpeech":"noun","translationUz":"jihat","definitionEn":"one part or characteristic of a situation"},{"testNo":2,"passageNo":3,"surface":"fascinating","partOfSpeech":"adjective","translationUz":"juda qiziqarli","definitionEn":"extremely interesting"},{"testNo":2,"passageNo":3,"surface":"sociology","partOfSpeech":"noun","translationUz":"sotsiologiya","definitionEn":"the scientific study of society"},{"testNo":2,"passageNo":3,"surface":"compose","partOfSpeech":"verb","translationUz":"yozib yaratmoq","definitionEn":"to produce a written work"},{"testNo":2,"passageNo":3,"surface":"biography","partOfSpeech":"noun","translationUz":"tarjimai hol","definitionEn":"an account of a person's life"},{"testNo":2,"passageNo":3,"surface":"cultural historian","partOfSpeech":"noun phrase","translationUz":"madaniyat tarixchisi","definitionEn":"a researcher who studies the history of culture"},{"testNo":2,"passageNo":3,"surface":"published literature","partOfSpeech":"noun phrase","translationUz":"chop etilgan adabiyotlar","definitionEn":"written works made publicly available"},{"testNo":2,"passageNo":3,"surface":"century","partOfSpeech":"noun","translationUz":"asr","definitionEn":"a period of one hundred years"},{"testNo":2,"passageNo":3,"surface":"happy accident","partOfSpeech":"noun phrase","translationUz":"baxtli tasodif","definitionEn":"an unexpected event that brings a beneficial result"},{"testNo":2,"passageNo":3,"surface":"pleasant surprise","partOfSpeech":"noun phrase","translationUz":"yoqimli kutilmagan hodisa","definitionEn":"a welcome event that happens unexpectedly"},{"testNo":2,"passageNo":3,"surface":"fairy tale","partOfSpeech":"noun phrase","translationUz":"ertak","definitionEn":"a traditional story with imaginary events or characters"},{"testNo":2,"passageNo":3,"surface":"heroes","partOfSpeech":"noun","translationUz":"qahramonlar","definitionEn":"central figures in a story"},{"testNo":2,"passageNo":3,"surface":"curiosities","partOfSpeech":"noun","translationUz":"noyob buyumlar","definitionEn":"rare or unusual objects of interest"},{"testNo":2,"passageNo":3,"surface":"unexpected","partOfSpeech":"adjective","translationUz":"kutilmagan","definitionEn":"not anticipated in advance"},{"testNo":2,"passageNo":3,"surface":"capacity","partOfSpeech":"noun","translationUz":"qobiliyat","definitionEn":"the ability to do something"},{"testNo":2,"passageNo":3,"surface":"community","partOfSpeech":"noun","translationUz":"hamjamiyat","definitionEn":"a group sharing a common interest or activity"},{"testNo":2,"passageNo":3,"surface":"vigorously","partOfSpeech":"adverb","translationUz":"qizg‘in tarzda","definitionEn":"with great force or intensity"},{"testNo":2,"passageNo":3,"surface":"contested","partOfSpeech":"verb","translationUz":"bahsga sabab bo‘lgan","definitionEn":"disputed or challenged"},{"testNo":2,"passageNo":3,"surface":"unplanned","partOfSpeech":"adjective","translationUz":"rejalashtirilmagan","definitionEn":"not arranged or intended in advance"},{"testNo":2,"passageNo":3,"surface":"emphasise","partOfSpeech":"verb","translationUz":"ta’kidlamoq","definitionEn":"to give special importance to something"},{"testNo":2,"passageNo":3,"surface":"physiologist","partOfSpeech":"noun","translationUz":"fiziolog olim","definitionEn":"a scientist studying how living organisms function"},{"testNo":2,"passageNo":3,"surface":"immunologist","partOfSpeech":"noun","translationUz":"immunolog olim","definitionEn":"a scientist specialising in the immune system"},{"testNo":2,"passageNo":3,"surface":"unintentionally","partOfSpeech":"adverb","translationUz":"bexosdan","definitionEn":"without intending to do something"},{"testNo":2,"passageNo":3,"surface":"current-carrying wire","partOfSpeech":"noun phrase","translationUz":"tok o‘tkazuvchi sim","definitionEn":"a wire through which electric current flows"},{"testNo":2,"passageNo":3,"surface":"magnetic needle","partOfSpeech":"noun phrase","translationUz":"magnit mili","definitionEn":"a narrow magnetic pointer responding to a magnetic field"},{"testNo":2,"passageNo":3,"surface":"sufficiency","partOfSpeech":"noun","translationUz":"yetarlilik","definitionEn":"the quality of being enough for a purpose"},{"testNo":2,"passageNo":3,"surface":"rational","partOfSpeech":"adjective","translationUz":"oqilona","definitionEn":"based on reason and logical thought"},{"testNo":2,"passageNo":3,"surface":"method","partOfSpeech":"noun","translationUz":"usul","definitionEn":"a systematic way of doing something"},{"testNo":2,"passageNo":3,"surface":"insisted","partOfSpeech":"verb","translationUz":"qat’iy ta’kidladi","definitionEn":"stated firmly and persistently"},{"testNo":2,"passageNo":3,"surface":"collectors","partOfSpeech":"noun","translationUz":"yig‘uvchilar","definitionEn":"people who collect objects as a hobby or profession"},{"testNo":2,"passageNo":3,"surface":"skill","partOfSpeech":"noun","translationUz":"mahorat","definitionEn":"the ability to do something well"},{"testNo":2,"passageNo":3,"surface":"exploited","partOfSpeech":"verb","translationUz":"foydalandi","definitionEn":"used something to achieve a purpose"},{"testNo":2,"passageNo":3,"surface":"stress","partOfSpeech":"verb","translationUz":"alohida urg‘u bermoq","definitionEn":"to place special emphasis on something"},{"testNo":2,"passageNo":3,"surface":"significant","partOfSpeech":"adjective","translationUz":"sezilarli","definitionEn":"important or large enough to matter"},{"testNo":2,"passageNo":3,"surface":"dangerous","partOfSpeech":"adjective","translationUz":"xavfli","definitionEn":"likely to cause harm"},{"testNo":2,"passageNo":3,"surface":"basis","partOfSpeech":"noun","translationUz":"asos","definitionEn":"the underlying support or reason for something"},{"testNo":2,"passageNo":3,"surface":"notice","partOfSpeech":"verb","translationUz":"payqamoq","definitionEn":"to become aware of something"},{"testNo":2,"passageNo":3,"surface":"potential","partOfSpeech":"adjective","translationUz":"ehtimoliy yoki mumkin bo‘lgan","definitionEn":"possible but not yet realised"},{"testNo":2,"passageNo":3,"surface":"constructive","partOfSpeech":"adjective","translationUz":"foydali va amaliy","definitionEn":"helping to achieve a positive result"},{"testNo":2,"passageNo":3,"surface":"systematic","partOfSpeech":"adjective","translationUz":"tizimli","definitionEn":"carried out according to an organised method"},{"testNo":2,"passageNo":3,"surface":"preparation","partOfSpeech":"noun","translationUz":"tayyorgarlik","definitionEn":"the act of getting ready for something"},{"testNo":2,"passageNo":3,"surface":"closer inspection","partOfSpeech":"noun phrase","translationUz":"chuqurroq tekshiruv","definitionEn":"a more careful examination"},{"testNo":2,"passageNo":3,"surface":"resonance","partOfSpeech":"noun","translationUz":"kuchli aks-sado","definitionEn":"a lasting influence or response"},{"testNo":2,"passageNo":3,"surface":"planned science","partOfSpeech":"noun phrase","translationUz":"rejalashtirilgan ilmiy tadqiqot","definitionEn":"research conducted according to predetermined plans"},{"testNo":2,"passageNo":3,"surface":"inhabitants","partOfSpeech":"noun","translationUz":"yashovchilar","definitionEn":"people who live in a particular place"},{"testNo":2,"passageNo":3,"surface":"pioneers","partOfSpeech":"noun","translationUz":"kashshoflar","definitionEn":"people who are among the first in a field"},{"testNo":2,"passageNo":3,"surface":"industrial research","partOfSpeech":"noun phrase","translationUz":"sanoat tadqiqotlari","definitionEn":"scientific investigation conducted for industrial purposes"},{"testNo":2,"passageNo":3,"surface":"overly rigid","partOfSpeech":"adjective phrase","translationUz":"haddan tashqari qattiq","definitionEn":"too strict or inflexible"},{"testNo":2,"passageNo":3,"surface":"planning","partOfSpeech":"noun","translationUz":"rejalashtirish","definitionEn":"the process of making plans"},{"testNo":2,"passageNo":3,"surface":"rationality","partOfSpeech":"noun","translationUz":"oqilonalik","definitionEn":"the quality of being based on reason"},{"testNo":2,"passageNo":3,"surface":"uncertainty","partOfSpeech":"noun","translationUz":"noaniqlik","definitionEn":"the state of not knowing what will happen"},{"testNo":2,"passageNo":3,"surface":"satisfactory","partOfSpeech":"adjective","translationUz":"qoniqarli","definitionEn":"meeting an acceptable standard"},{"testNo":2,"passageNo":3,"surface":"drifting","partOfSpeech":"verb","translationUz":"shamol yo‘nalishida oqib ketish","definitionEn":"moving without controlling the direction"},{"testNo":2,"passageNo":3,"surface":"determinate","partOfSpeech":"adjective","translationUz":"aniq belgilangan","definitionEn":"having clearly defined limits or results"},{"testNo":2,"passageNo":3,"surface":"cause and effect","partOfSpeech":"noun phrase","translationUz":"sabab va oqibat","definitionEn":"a relationship in which one event produces another"},{"testNo":2,"passageNo":3,"surface":"bowels","partOfSpeech":"noun","translationUz":"ichki qatlamlar","definitionEn":"the deepest interior parts of something"},{"testNo":2,"passageNo":3,"surface":"corporate capitalism","partOfSpeech":"noun phrase","translationUz":"korporativ kapitalizm","definitionEn":"an economic system dominated by corporations"},{"testNo":2,"passageNo":3,"surface":"productive","partOfSpeech":"adjective","translationUz":"samarali","definitionEn":"producing useful results"},{"testNo":2,"passageNo":3,"surface":"evidence","partOfSpeech":"noun","translationUz":"dalillar","definitionEn":"information supporting a conclusion"},{"testNo":2,"passageNo":3,"surface":"criteria","partOfSpeech":"noun","translationUz":"mezonlar","definitionEn":"standards used to make a judgment"},{"testNo":2,"passageNo":3,"surface":"consequences","partOfSpeech":"noun","translationUz":"oqibatlar","definitionEn":"results of actions or events"}],"corrections":[{"testNo":1,"passageNo":1,"surface":"win","partOfSpeech":"verb","translationUz":"g‘alaba qozonmoq","definitionEn":"to defeat an opponent in a battle or competition"},{"testNo":1,"passageNo":1,"surface":"established","partOfSpeech":"verb","translationUz":"ta’sis etdi","definitionEn":"to set up or institute something officially"},{"testNo":1,"passageNo":1,"surface":"shower","partOfSpeech":"verb","translationUz":"dush qabul qilmoq","definitionEn":"to wash the body under running water"},{"testNo":1,"passageNo":1,"surface":"employed","partOfSpeech":"verb","translationUz":"qo‘llanilgan","definitionEn":"to make use of a method or substance"},{"testNo":1,"passageNo":1,"surface":"technology","partOfSpeech":"noun","translationUz":"texnologiya","definitionEn":"the practical application of scientific knowledge to industry"},{"testNo":1,"passageNo":1,"surface":"heated","partOfSpeech":"verb","translationUz":"qizdirilgan","definitionEn":"made hotter by applying heat"},{"testNo":1,"passageNo":2,"surface":"capital","partOfSpeech":"noun","translationUz":"poytaxt","definitionEn":"the city that serves as the seat of national government"},{"testNo":1,"passageNo":2,"surface":"insurance","partOfSpeech":"noun","translationUz":"falokatga qarshi ehtiyot chorasi","definitionEn":"an arrangement that protects against a possible future loss"},{"testNo":1,"passageNo":2,"surface":"perfect","partOfSpeech":"adjective","translationUz":"juda mos","definitionEn":"ideally suited to a particular purpose"},{"testNo":1,"passageNo":2,"surface":"environmental","partOfSpeech":"adjective","translationUz":"atrof-muhitga oid","definitionEn":"related to the conditions of the natural surroundings"},{"testNo":1,"passageNo":3,"surface":"product","partOfSpeech":"noun","translationUz":"natija","definitionEn":"something that results from a process or cause"},{"testNo":1,"passageNo":3,"surface":"vehicle","partOfSpeech":"noun","translationUz":"ifodalash vositasi","definitionEn":"a means by which ideas or information are communicated"},{"testNo":1,"passageNo":3,"surface":"contrast","partOfSpeech":"noun","translationUz":"qarama-qarshilik","definitionEn":"a clear difference between two things being compared"},{"testNo":1,"passageNo":3,"surface":"truth","partOfSpeech":"noun","translationUz":"haqiqat","definitionEn":"a fact or principle that is accepted as true"}],"offsetRepairs":[{"testNo":1,"passageNo":2,"id":"9f3f5c58-7146-4823-ad5d-655007d77169","surface":"predator","expectedStart":176,"matchOrdinal":1},{"testNo":1,"passageNo":2,"id":"47ed1da8-865f-4a1e-8cf5-d33dbdfd8da6","surface":"sanctuary","expectedStart":1172,"matchOrdinal":5},{"testNo":1,"passageNo":3,"id":"f7b348f2-d361-49d6-8468-4fcac40cee9e","surface":"non-verbal","expectedStart":11,"matchOrdinal":1}]}$plan$::jsonb;
  v_check record;
  v_repair record;
  v_item record;
  v_old record;
  v_passage_id uuid;
  v_body text;
  v_word text;
  v_part text;
  v_lexical_type text;
  v_unit_id uuid;
  v_lexeme_id uuid;
  v_sense_key text;
  v_regex text;
  v_start integer;
  v_total integer;
  v_ordinal integer;
  v_rows integer;
  v_repaired integer := 0;
  v_corrected integer := 0;
  v_inserted integer := 0;
BEGIN
  PERFORM pg_advisory_xact_lock(11061401);

  -- Fail before any mutation if any source text or catalogue slot changed.
  FOR v_check IN SELECT key, value FROM jsonb_each_text(v_plan->'passages') LOOP
    SELECT COUNT(*), MIN(body_text) INTO v_total, v_body
      FROM reading_passages
      WHERE test_no=split_part(v_check.key,'-',1)::integer
        AND passage_no=split_part(v_check.key,'-',2)::integer;
    IF v_total <> 1 OR v_body IS NULL
       OR encode(extensions.digest(v_body,'sha256'),'hex') <> v_check.value THEN
      RAISE EXCEPTION 'Reading source checksum mismatch: %', v_check.key;
    END IF;
  END LOOP;

  -- Repair exact incorrect spans in passages 002 and 003 without changing IDs.
  FOR v_repair IN
    SELECT * FROM jsonb_to_recordset(v_plan->'offsetRepairs')
      AS r("testNo" integer,"passageNo" integer,id text,surface text,
           "expectedStart" integer,"matchOrdinal" integer)
  LOOP
    SELECT p.id,p.body_text,o.start_char,o.end_char,o.surface_form
      INTO v_old
      FROM lexical_occurrences o
      JOIN reading_passages p ON p.id=o.passage_id
      WHERE o.id=v_repair.id::uuid
        AND p.test_no=v_repair."testNo"
        AND p.passage_no=v_repair."passageNo";
    IF NOT FOUND OR lower(v_old.surface_form) <> lower(v_repair.surface) THEN
      RAISE EXCEPTION 'Reading repair target changed: %',v_repair.id;
    END IF;
    v_regex:='(?i)(?<![[:alpha:]])'||v_repair.surface||'(?![[:alpha:]])';
    v_start:=regexp_instr(v_old.body_text,v_regex,1,v_repair."matchOrdinal")-1;
    IF v_start<0 OR lower(substr(v_old.body_text,v_start+1,length(v_repair.surface)))
       <> lower(v_repair.surface) THEN
      RAISE EXCEPTION 'Reading repair missing or mismatched surface: %',v_repair.id;
    END IF;
    IF v_old.start_char=v_start AND v_old.end_char=v_start+length(v_repair.surface) THEN
      CONTINUE;
    END IF;
    IF v_old.start_char<>v_repair."expectedStart"
       OR EXISTS(SELECT 1 FROM lexical_occurrences o
         WHERE o.passage_id=v_old.id AND o.id<>v_repair.id::uuid
           AND o.start_char<v_start+length(v_repair.surface) AND o.end_char>v_start) THEN
      RAISE EXCEPTION 'Reading repair conflicts with prior span: %',v_repair.id;
    END IF;
    UPDATE lexical_occurrences o
      SET start_char=v_start,end_char=v_start+length(v_repair.surface),
        sentence_text=substr(v_old.body_text,greatest(1,v_start-120),260)
      WHERE o.id=v_repair.id::uuid;
    v_repaired:=v_repaired+1;
  END LOOP;

  -- Correct polysemous meanings in 001-003 and enrich 004-006.
  FOR v_item IN
    SELECT x.kind,x.test_no,x.passage_no,x.surface,x.pos,x.uz,x.definition
    FROM (
      SELECT 'correction'::text AS kind,c."testNo" AS test_no,
        c."passageNo" AS passage_no,c.surface,c."partOfSpeech" AS pos,
        c."translationUz" AS uz,c."definitionEn" AS definition
        FROM jsonb_to_recordset(v_plan->'corrections')
        AS c("testNo" integer,"passageNo" integer,surface text,
             "partOfSpeech" text,"translationUz" text,"definitionEn" text)
      UNION ALL
      SELECT 'new'::text AS kind,t."testNo" AS test_no,
        t."passageNo" AS passage_no,t.surface,t."partOfSpeech" AS pos,
        t."translationUz" AS uz,t."definitionEn" AS definition
        FROM jsonb_to_recordset(v_plan->'terms')
        AS t("testNo" integer,"passageNo" integer,surface text,
             "partOfSpeech" text,"translationUz" text,"definitionEn" text)
    ) AS x
    ORDER BY CASE WHEN x.kind='correction' THEN 0 ELSE 1 END,
      LENGTH(x.surface) DESC,x.test_no,x.passage_no,x.surface
  LOOP
    SELECT id,body_text INTO v_passage_id,v_body FROM reading_passages
      WHERE test_no=v_item.test_no AND passage_no=v_item.passage_no;
    IF v_passage_id IS NULL THEN
      RAISE EXCEPTION 'Reading passage missing: %-%',v_item.test_no,v_item.passage_no;
    END IF;
    v_word:=lower(trim(regexp_replace(v_item.surface,'[[:space:]]+',' ','g')));
    v_part:=lower(trim(v_item.pos));
    v_regex:='(?i)(?<![[:alpha:]])'||v_item.surface||'(?![[:alpha:]])';
    v_total:=regexp_count(v_body,v_regex);
    IF v_total<1 THEN
      RAISE EXCEPTION 'Reading vocabulary surface absent: %-%, %',v_item.test_no,v_item.passage_no,v_item.surface;
    END IF;
    IF v_item.kind='correction' THEN
      SELECT COUNT(*) INTO v_rows FROM lexical_occurrences
        WHERE passage_id=v_passage_id AND lower(surface_form)=v_word;
      IF v_rows<>1 THEN
        RAISE EXCEPTION 'Reading correction cardinality changed: %-%, %',v_item.test_no,v_item.passage_no,v_item.surface;
      END IF;
    END IF;
    v_lexical_type:=CASE v_part
      WHEN 'noun phrase' THEN 'noun_phrase'
      WHEN 'verb phrase' THEN 'verb_phrase'
      WHEN 'phrasal verb' THEN 'phrasal_verb'
      WHEN 'idiom' THEN 'idiom'
      WHEN 'collocation' THEN 'collocation'
      WHEN 'fixed expression' THEN 'fixed_expression'
      WHEN 'compound' THEN 'compound'
      WHEN 'phrase' THEN 'phrase'
      ELSE CASE WHEN position(' ' IN v_word)>0 THEN 'phrase' ELSE 'word' END
    END;
    -- Reuse a lexical unit of the same lemma, POS and lexical type.
    INSERT INTO lexical_units
      (language,lemma,lemma_norm,part_of_speech,lexical_type,
       is_function_word,provenance)
      VALUES('en',v_item.surface,v_word,v_part,v_lexical_type,false,
             'general_reading_context')
      ON CONFLICT(language,lemma_norm,part_of_speech,lexical_type) DO NOTHING;
    SELECT id INTO STRICT v_unit_id FROM lexical_units
      WHERE language='en' AND lemma_norm=v_word
        AND part_of_speech=v_part AND lexical_type=v_lexical_type;
    INSERT INTO lexical_unit_forms
      (lexical_unit_id,form,form_norm,form_type)
      VALUES(v_unit_id,v_item.surface,v_word,'lemma')
      ON CONFLICT(lexical_unit_id,form_norm) DO NOTHING;

    -- The v2 key is SHA256(JSON([normalised term, POS, English meaning])).
    v_sense_key:='v2:'||encode(extensions.digest(
      replace(json_build_array(v_word,v_part,lower(trim(v_item.definition)))::text,
              '", "', '","'),'sha256'),'hex');
    SELECT id INTO v_lexeme_id FROM lexemes
      WHERE sense_key=v_sense_key;
    IF v_lexeme_id IS NULL THEN
      -- Honor exact legacy senses too; do not duplicate identical meanings.
      SELECT id INTO v_lexeme_id FROM lexemes
        WHERE lower(trim(term))=v_word AND lower(trim(coalesce(part_of_speech,'')))=v_part
          AND lower(trim(definition_en))=lower(trim(v_item.definition))
        ORDER BY id LIMIT 1;
    END IF;
    IF v_lexeme_id IS NULL THEN
      INSERT INTO lexemes
        (term,part_of_speech,definition_en,translation_uz,example_sentence,
         lexical_unit_id,sense_key,provenance,verification_status,import_batch)
        VALUES(v_item.surface,v_item.pos,v_item.definition,v_item.uz,
               NULL,v_unit_id,v_sense_key,'general_reading_context',
               'context_checked','20261114-passages-001-006')
        ON CONFLICT(sense_key) DO NOTHING
        RETURNING id INTO v_lexeme_id;
      IF v_lexeme_id IS NULL THEN
        SELECT id INTO STRICT v_lexeme_id FROM lexemes WHERE sense_key=v_sense_key;
      END IF;
    END IF;
    SELECT coalesce(lexical_unit_id,v_unit_id) INTO v_unit_id
      FROM lexemes WHERE id=v_lexeme_id;

    IF v_item.kind='correction' THEN
      UPDATE lexical_occurrences
        SET lexeme_id=v_lexeme_id,lexical_unit_id=v_unit_id,
            resolution_status='resolved',resolution_source='context_editorial'
        WHERE passage_id=v_passage_id AND lower(surface_form)=v_word;
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      v_corrected:=v_corrected+v_rows;
      CONTINUE;
    END IF;

    FOR v_ordinal IN 1..v_total LOOP
      v_start:=regexp_instr(v_body,v_regex,1,v_ordinal)-1;
      IF v_start<0 OR lower(substr(v_body,v_start+1,length(v_item.surface)))
        <> lower(v_item.surface) THEN
        RAISE EXCEPTION 'Source text shifted while linking: %-%, %',v_item.test_no,v_item.passage_no,v_item.surface;
      END IF;
      -- Keep pre-existing curated multiword senses authoritative.
      IF EXISTS(SELECT 1 FROM lexical_occurrences o
          WHERE o.passage_id=v_passage_id
            AND o.start_char<v_start+length(v_item.surface)
            AND o.end_char>v_start) THEN
        CONTINUE;
      END IF;
      INSERT INTO lexical_occurrences
        (source_type,passage_id,start_char,end_char,surface_form,lexeme_id,
         lexical_unit_id,resolution_status,resolution_source,sentence_text,
         occurrence_type,is_target_vocabulary)
        VALUES('reading',v_passage_id,v_start,v_start+length(v_item.surface),
               substr(v_body,v_start+1,length(v_item.surface)),
               v_lexeme_id,v_unit_id,'resolved','context_editorial',
               substr(v_body,greatest(1,v_start-120),260),
               'vocabulary',true)
        ON CONFLICT(passage_id,start_char,end_char) DO NOTHING;
      GET DIAGNOSTICS v_rows=ROW_COUNT;
      v_inserted:=v_inserted+v_rows;
    END LOOP;
  END LOOP;
  RAISE NOTICE 'reading contextual links: repaired %, corrected %, added %',
    v_repaired,v_corrected,v_inserted;
END
$executor$;
